def parse_pairs(lines):
    result = {}
    for line in lines:
        # Skip blank lines
        if line.strip() == '':
            continue
        # Check for '=' in the line
        if '=' not in line:
            raise ValueError("Missing '=' in line")
        # Split on first '=' only
        key, value = line.split('=', 1)
        # Strip whitespace from key and value
        key = key.strip()
        value = value.strip()
        # Reject empty key
        if key == '':
            raise ValueError("Empty key")
        # Let later duplicate keys win (just assign)
        result[key] = value
    return result

